import fs from 'node:fs/promises'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const outputRoot = path.join(root, '.output/public')
const redirects = JSON.parse(await fs.readFile(path.join(root, 'data/legacy-redirects.json'), 'utf8'))

await fs.access(path.join(outputRoot, '404.html'))
const ignoredAssets = [
  '# Generated by scripts/prepare-cloudflare-assets.mjs.',
  '# Legacy compatibility pages stay available to generic static hosts but are',
  '# excluded from Workers Assets so the Worker can return real HTTP 301 responses.',
  ...Object.keys(redirects).flatMap((source) => {
    const relative = source.slice(1)
    return source.endsWith('.html') ? [relative] : [`${relative}/**`]
  }),
  '',
]

await fs.writeFile(path.join(outputRoot, '.assetsignore'), ignoredAssets.join('\n'))
console.log(`Prepared Workers Assets exclusions for ${Object.keys(redirects).length} legacy routes.`)
